    'asterisk_settings.rtp_help_body' => 'Styrer hvilket portområde som bærer lyd (RTP) og om Asterisk avviser lyd som kommer fra en uventet kilde. Denne filen (<code>/etc/asterisk/rtp.conf</code>) genereres nå av panelet; manuelle endringer på serveren går tapt ved neste «Bruk».',
