    'sound_packs.help_body' => 'Laster ned og installerer Asterisks offisielle systemmeldinger og ventemusikk fra <code>downloads.asterisk.org</code>. Hver pakke er ett språk i ett format; Asterisk spiller av formatet som passer til samtalens kodek og omkoder ellers (g722 for G.722, ulaw/alaw for operatører).<br>- <strong>Core:</strong> systemmeldinger, sifre, talepost. <strong>Extra:</strong> ekstra meldinger; kjernepakken for samme språk må installeres først.<br>- <strong>Ventemusikk (opsound):</strong> installeres i <code>/var/lib/asterisk/moh/opsound</code>; for å spille den av, opprett en MOH-klasse med navnet <strong>opsound</strong> i fanen Ventemusikk.<br>- <strong>Türkçe (AiPBX):</strong> AiPBX’ egne tyrkiske meldinger (GitHub-utgivelse, SHA256-verifisert); standardspråket er tyrkisk, så hvis du fjerner dem, blir systemmeldingene stille. Fjerning sletter bare filene pakken installerte.',
