    'certificates.help_title' => 'Sertifikatveiledning',
    'certificates.help_body' => 'Portalen (HTTPS), WebRTC TURNS og SIP-TLS/WSS deler ett sertifikat; endringer her tas i bruk i Apache, coturn og Asterisk samtidig. <b>Let\'s Encrypt</b> er gratis og fornyer seg selv; domenet må peke til denne serveren, og port 80 må være tilgjengelig fra internett. Hvis organisasjonen din har et sertifikat, kan du <b>laste det opp</b> (PEM eller PFX); opplastede sertifikater fornyes ikke automatisk, så last opp et nytt før det utløper. Med et <b>selvsignert</b> sertifikat viser nettlesere en advarsel, og TURNS fungerer ikke i nettlesere: WebRTC-samtaler bak brannmurer kan mangle lyd.',
