    'queue_reports.help_title' => 'Veiledning for kørapporter',
    'queue_reports.help_body' => 'Hvert anrop som kommer inn i en kø, telles én gang. <b>Besvart</b>: koblet til en agent. <b>Tapt</b>: innringeren la på under ventingen, eller køen fikk tidsavbrudd. <b>Kort avbrudd</b>: la på innen %d sekunder; holdes utenfor servicenivået. <b>Servicenivå</b>: anrop besvart innen målet, av alle anrop unntatt korte avbrudd. <b>ASA</b>: gjennomsnittlig ventetid for besvarte anrop. <b>AHT</b>: gjennomsnittlig samtaletid. <b>Svarprosent</b> (agent): hvor ofte agenten svarte når køen ringte til vedkommende. <b>Tilbakeringing</b>: et tapt anrop regnes som løst når nummeret senere ble ringt fra et internnummer, eller ringte på nytt og ble besvart. Dataene kommer fra Asterisks kølogg; rapporten kan lastes ned som PDF eller Excel.',
