    'ai_tts.help_body' => 'Gjør tekst om til naturlig tale med skytjenester (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Lytt til resultatet, last det ned som MP3, eller lagre det som en <b>kunngjøring</b> med ett klikk: det konverteres til Asterisks format (8 kHz WAV) og legges til under Lyder &amp; kunngjøringer for IVR-er, innkommende ruter og tidsbetingelser (trer i kraft etter Ta i bruk). <b>Disse tjenestene koster penger</b> og faktureres per tegn; hver syntese lagres i historikken med antall tegn. Tilgangsnøklene hentes fra hver leverandørs konsoll, lagres kryptert og vises aldri på siden igjen.',
