    'mailtpl.invite_new.subject' => '[{brand}] Kontoen din er opprettet - angi passordet ditt',
    'mailtpl.invite_new.body' => '<p>Hei {name},</p>{mobile_section}<p>Kontoen din på sentralbordet <strong>{brand}</strong> er klar. Angi passordet ditt med knappen nedenfor for å logge inn.</p>{account_details}{reset_button}<p>Hvis knappen ikke virker, åpner du denne lenken: {reset_link}</p><p><em>Passordlenken er gyldig i 48 timer og virker én gang. Hvis du ikke ventet denne e-posten, kontakter du systemadministratoren.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Lenken din for pålogging og passord',
    'mailtpl.invite.body' => '<p>Hei {name},</p>{mobile_section}<p>Her er en ny lenke for å angi passordet ditt for <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Hvis knappen ikke virker, åpner du denne lenken: {reset_link}</p><p><em>Passordlenken er gyldig i 48 timer og virker én gang. Hvis du ikke har bedt om den, kontakter du systemadministratoren.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Tilbakestill passordet ditt',
    'mailtpl.password_reset.body' => '<p>Hei {name},</p><p>Det er bedt om tilbakestilling av passordet for kontoen din <strong>{username}</strong>.</p>{reset_button}<p>Hvis knappen ikke virker, åpner du denne lenken: {reset_link}</p><p><em>Lenken er gyldig i 30 minutter. Hvis du ikke har bedt om den, kan du se bort fra denne e-posten; passordet ditt forblir det samme.</em></p>',
    'mailtpl.voicemail.subject' => 'Ny talemelding fra {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Hei {name},</p><p>Du har en ny melding i taleposten <strong>{mailbox}</strong>.</p><ul><li><strong>Fra:</strong> {caller}</li><li><strong>Mottatt:</strong> {date}</li><li><strong>Lengde:</strong> {duration}</li></ul><p>Hvis opptaket er vedlagt, kan du spille det av direkte her. Du kan også lytte til det i portalen ({portal_link}) eller ved å ringe *97.</p>',
    'mailtpl.fax_received.subject' => 'Ny faks mottatt - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>En ny faks er mottatt.</p><ul><li><strong>Enhet:</strong> {department}</li><li><strong>Faksnummer:</strong> {did}</li><li><strong>Fra:</strong> {caller}</li><li><strong>Sider:</strong> {pages}</li><li><strong>Mottatt:</strong> {date}</li></ul><p>Faksen legges ved som PDF når dette er slått på. Alle fakser ligger i faksinnboksen: {portal_link}</p>',
