    'storage.help_title' => 'Hvor chatfiler lagres',
    'storage.help_body' => '<p>Chatvedlegg, miniatyrbildene deres og gruppebilder lagres som standard på serverens disk (<code>/var/lib/aipbx/chat_files</code>). Med en S3-kompatibel lagring (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) havner de i stedet i en bøtte, og store filer holdes unna PBX-en.</p><p>Nedlastinger går fortsatt via chattjenesten, så bare deltakerne i en chat kan åpne filene i den; bøtten kan forbli privat. Filer som ble lagret før byttet, leveres fortsatt fra disken til du flytter dem. Bøtteinnstillingene kontrolleres før de lagres.</p><p>Samtaleopptak, talepost og fakser blir værende på den lokale disken.</p>',
