    'web_widgets.help_body' => 'En widget setter en «Ring oss»-knapp på et hvilket som helst nettsted. Besøkende snakker med deg fra nettleseren over WebRTC, eller legger igjen nummeret sitt slik at PBX-en ringer dem. Lim inn énlinjeskoden på nettstedet (eller i WordPress-tillegget), og trykk <strong>Bruk</strong> etter lagring.',
    'web_widgets.help_number' => 'Nummer:',
    'web_widgets.help_number_desc' => 'En widget kommer inn i PBX-en som en trunk. Nummeret er DID-en for disse samtalene i rapporter og CDR; den besøkende velger aldri hvor samtalen går.',
    'web_widgets.help_security' => 'Sikkerhet:',
    'web_widgets.help_security_desc' => 'Bare de tillatte nettstedene kan bruke widgeten. Hver samtale krever et engangstoken, og grensene (per IP, per dag, samtidige samtaler, samtalelengde) gjelder for hver forespørsel. Hver forespørsel logges nedenfor.',
    'web_widgets.help_callback' => 'Tilbakeringing:',
    'web_widgets.help_callback_desc' => 'PBX-en ringer den besøkende via den valgte utgående ruten og sender vedkommende til målet når de svarer. Bare numre som starter med de tillatte prefiksene, blir ringt, og en daglig grense er påkrevd.',
